            if (currentTaxCode === newTaxCode) {
                Navigation.goBack(ROUTES.WORKSPACE_TAX_EDIT.getRoute(policyID, currentTaxCode));
                return;
            }

            setPolicyTaxCode(policyID, currentTaxCode, newTaxCode);
            Navigation.goBack(ROUTES.WORKSPACE_TAX_EDIT.getRoute(policyID, currentTaxCode));
        },
        [currentTaxCode, policyID],
    );

